      o_mean_mean_mean_p_p[i] = (K[69]*u8 + K[70]*u7 + K[71]*u0 + K[72]*u1 + K[73]*u2 + K[74]*u3 + K[75]*u4 + K[76]*u9 + K[77]*u5 + K[78]*u6 + K[79]*Z + K[80]*R + K[81]) * std::pow(im, 3);
