      o_mean_mean_d_p_p[i] = (K[114]*u8 + K[115]*u7 + K[116]*u0 + K[117]*u1 + K[118]*u2 + K[119]*u3 + K[120]*u4 + K[121]*u9 + K[122]*u5 + K[123]*u6 + K[124]*Z + K[125]*R + K[126]) * std::pow(im, 2);
      o_mean_mean_p_p_p[i] = (K[135]*u10 + K[136]*u8 + K[137]*u7 + K[138]*u0 + K[139]*u1 + K[140]*u2 + K[141]*u3 + K[142]*u11 + K[143]*u4 + K[144]*u9 + K[145]*u5 + K[146]*u6 + K[147]*Z + K[148]*R + K[149]) * std::pow(im, 2);
      o_mean_d_d_d_d[i] = (K[152]*u0 + K[153]*u1 + K[154]*u2 + K[155]*u3 + K[156]*u4 + K[157]*u5 + K[158]*Z + K[159]*R + K[160]) * im;
      o_mean_d_d_d_p[i] = (K[165]*u7 + K[166]*u0 + K[167]*u1 + K[168]*u2 + K[169]*u3 + K[170]*u4 + K[171]*u5 + K[172]*u6 + K[173]*Z + K[174]*R + K[175]) * im;
