      o_mean_d_p_p_p[i] = (K[203]*u10 + K[204]*u8 + K[205]*u7 + K[206]*u0 + K[207]*u1 + K[208]*u2 + K[209]*u3 + K[210]*u11 + K[211]*u4 + K[212]*u9 + K[213]*u5 + K[214]*u6 + K[215]*Z + K[216]*R + K[217]) * im;
      o_mean_p_p_p_p[i] = (K[228]*u12 + K[229]*u10 + K[230]*u8 + K[231]*u7 + K[232]*u0 + K[233]*u1 + K[234]*u2 + K[235]*u13 + K[236]*u3 + K[237]*u11 + K[238]*u4 + K[239]*u9 + K[240]*u5 + K[241]*u6 + K[242]*Z + K[243]*R + K[244]) * im;
      o_d_d_d_d_d[i] = (K[247]*u0 + K[248]*u1 + K[249]*u2 + K[250]*u3 + K[251]*u4 + K[252]*u5 + K[253]*Z + K[254]*R + K[255]);
      o_d_d_d_d_p[i] = (K[260]*u7 + K[261]*u0 + K[262]*u1 + K[263]*u2 + K[264]*u3 + K[265]*u4 + K[266]*u5 + K[267]*u6 + K[268]*Z + K[269]*R + K[270]);
