      o_d_d_p_p_p[i] = (K[298]*u10 + K[299]*u8 + K[300]*u7 + K[301]*u0 + K[302]*u1 + K[303]*u2 + K[304]*u3 + K[305]*u11 + K[306]*u4 + K[307]*u9 + K[308]*u5 + K[309]*u6 + K[310]*Z + K[311]*R + K[312]);
