// the coefficients of gengamma2_dexpected1_cpp, in double or in double-double
template <class T>
static void coef_gengamma2_dexpected1_cpp(const T& d, const T& p, const T* PAv, const T* Gv, const T& Bs, double* K) {
  (void) d; (void) p; (void) PAv; (void) Gv; (void) Bs;
  d7::gengamma2_coef_dexpected_mean_mean_mean<T>(d, p, PAv, Gv, Bs, K);
  d7::gengamma2_coef_dexpected_d_d_d<T>(d, p, PAv, Gv, Bs, K);
  d7::gengamma2_coef_dexpected_p_p_p<T>(d, p, PAv, Gv, Bs, K);
  d7::gengamma2_coef_dexpected1_rest<T>(d, p, PAv, Gv, Bs, K);
}

// first derivatives of the expected Hessian
// [[Rcpp::export]]
List gengamma2_dexpected1_cpp(NumericVector y, NumericVector mean_, NumericVector d_, NumericVector p_) {
  const int n = y.size();
  const int n_m = mean_.size(), n_d = d_.size(), n_p = p_.size();
  NumericVector o_mean_mean_mean(n);
  NumericVector o_mean_mean_d(n);
  NumericVector o_mean_mean_p(n);
  NumericVector o_d_d_mean(n);
  NumericVector o_d_d_d(n);
  NumericVector o_d_d_p(n);
  NumericVector o_p_p_mean(n);
  NumericVector o_p_p_d(n);
  NumericVector o_p_p_p(n);
  NumericVector o_mean_d_mean(n);
  NumericVector o_mean_d_d(n);
  NumericVector o_mean_d_p(n);
  NumericVector o_mean_p_mean(n);
  NumericVector o_mean_p_d(n);
  NumericVector o_mean_p_p(n);
  NumericVector o_d_p_mean(n);
  NumericVector o_d_p_d(n);
  NumericVector o_d_p_p(n);
  std::vector<double> K(18);
  double mv = 0.0, pv = 0.0, A0 = 0.0, Z0 = 0.0;
  double last_d = R_NaN, last_p = R_NaN;
  auto set_params = [&](int i) {
    mv = mean_[i % n_m]; const double dv = d_[i % n_d]; pv = p_[i % n_p];
    // the coefficients depend on (d, p) alone
    if (dv == last_d && pv == last_p) return;
    last_d = dv; last_p = pv;
    const double k0d = dv / pv;
    if (k0d < GG2_KC && dv < GG2_DC) {
      // no cancellation to speak of: double
      const double k1d = (dv + 1.0) / pv;
      double PAv[12], Gv[12];
      (void) k1d; (void) PAv; (void) Gv;
      PAv[1] = R::psigamma(k0d, 1.0);
      PAv[2] = R::psigamma(k0d, 2.0);
      Gv[0] = R::psigamma(k1d, 0.0) - R::psigamma(k0d, 0.0);
      Gv[1] = R::psigamma(k1d, 1.0) - R::psigamma(k0d, 1.0);
      coef_gengamma2_dexpected1_cpp<double>(dv, pv, PAv, Gv, 0.0, K.data());
    } else {
      const dd d(dv), p(pv);
      const dd k0 = d / p, k1 = (d + 1.0) / p;
      dd PAv[12], Gv[12];
      (void) k1; (void) PAv; (void) Gv;
      PAv[1] = dd_psi_n(k0, 1);
      PAv[2] = dd_psi_n(k0, 2);
      Gv[0] = dd_psi_diff(k0, k1, 0);
      Gv[1] = dd_psi_diff(k0, k1, 1);
      coef_gengamma2_dexpected1_cpp<dd>(d, p, PAv, Gv, dd(0.0), K.data());
    }
  };
  const bool scalar = n_m == 1 && n_d == 1 && n_p == 1;
  if (scalar) set_params(0);
  for (int i = 0; i < n; i++) {
    if (!scalar) set_params(i);
    const double im = 1.0 / mv;
    (void) im;
    o_mean_mean_mean[i] = d7::gengamma2_dexpected_mean_mean_mean(K.data(), im);
    o_mean_mean_d[i] = (K[1]) * std::pow(im, 2);
    o_mean_mean_p[i] = (K[2]) * std::pow(im, 2);
    o_d_d_mean[i] = (K[3]) * im;
    o_d_d_d[i] = d7::gengamma2_dexpected_d_d_d(K.data(), im);
    o_d_d_p[i] = (K[5]);
    o_p_p_mean[i] = (K[6]) * im;
    o_p_p_d[i] = (K[7]);
    o_p_p_p[i] = d7::gengamma2_dexpected_p_p_p(K.data(), im);
    o_mean_d_mean[i] = (K[9]) * std::pow(im, 2);
    o_mean_d_d[i] = (K[10]) * im;
    o_mean_d_p[i] = (K[11]) * im;
    o_mean_p_mean[i] = (K[12]) * std::pow(im, 2);
    o_mean_p_d[i] = (K[13]) * im;
    o_mean_p_p[i] = (K[14]) * im;
    o_d_p_mean[i] = (K[15]) * im;
    o_d_p_d[i] = (K[16]);
    o_d_p_p[i] = (K[17]);
  }
  (void) mv; (void) pv; (void) A0; (void) Z0;
  return List::create(Named("mean_mean_mean") = o_mean_mean_mean, Named("mean_mean_d") = o_mean_mean_d, Named("mean_mean_p") = o_mean_mean_p, Named("d_d_mean") = o_d_d_mean, Named("d_d_d") = o_d_d_d, Named("d_d_p") = o_d_d_p, Named("p_p_mean") = o_p_p_mean, Named("p_p_d") = o_p_p_d, Named("p_p_p") = o_p_p_p, Named("mean_d_mean") = o_mean_d_mean, Named("mean_d_d") = o_mean_d_d, Named("mean_d_p") = o_mean_d_p, Named("mean_p_mean") = o_mean_p_mean, Named("mean_p_d") = o_mean_p_d, Named("mean_p_p") = o_mean_p_p, Named("d_p_mean") = o_d_p_mean, Named("d_p_d") = o_d_p_d, Named("d_p_p") = o_d_p_p);
}

