// second derivatives of the expected Hessian
// [[Rcpp::export]]
List gengamma2_dexpected2_cpp(NumericVector y, NumericVector mean_, NumericVector d_, NumericVector p_) {
  const int n = y.size();
  const int n_m = mean_.size(), n_d = d_.size(), n_p = p_.size();
  NumericVector o_mean_mean_mean_mean(n);
  NumericVector o_mean_mean_d_d(n);
  NumericVector o_mean_mean_p_p(n);
  NumericVector o_mean_mean_mean_d(n);
  NumericVector o_mean_mean_mean_p(n);
  NumericVector o_mean_mean_d_p(n);
  NumericVector o_d_d_mean_mean(n);
  NumericVector o_d_d_d_d(n);
  NumericVector o_d_d_p_p(n);
  NumericVector o_d_d_mean_d(n);
  NumericVector o_d_d_mean_p(n);
  NumericVector o_d_d_d_p(n);
  NumericVector o_p_p_mean_mean(n);
  NumericVector o_p_p_d_d(n);
  NumericVector o_p_p_p_p(n);
  NumericVector o_p_p_mean_d(n);
  NumericVector o_p_p_mean_p(n);
  NumericVector o_p_p_d_p(n);
  NumericVector o_mean_d_mean_mean(n);
  NumericVector o_mean_d_d_d(n);
  NumericVector o_mean_d_p_p(n);
  NumericVector o_mean_d_mean_d(n);
  NumericVector o_mean_d_mean_p(n);
  NumericVector o_mean_d_d_p(n);
  NumericVector o_mean_p_mean_mean(n);
  NumericVector o_mean_p_d_d(n);
  NumericVector o_mean_p_p_p(n);
  NumericVector o_mean_p_mean_d(n);
  NumericVector o_mean_p_mean_p(n);
  NumericVector o_mean_p_d_p(n);
  NumericVector o_d_p_mean_mean(n);
  NumericVector o_d_p_d_d(n);
  NumericVector o_d_p_p_p(n);
  NumericVector o_d_p_mean_d(n);
  NumericVector o_d_p_mean_p(n);
  NumericVector o_d_p_d_p(n);
  std::vector<double> K(36);
  double mv = 0.0, pv = 0.0, A0 = 0.0, Z0 = 0.0;
  double last_d = R_NaN, last_p = R_NaN;
  auto set_params = [&](int i) {
    mv = mean_[i % n_m]; const double dv = d_[i % n_d]; pv = p_[i % n_p];
    // the coefficients depend on (d, p) alone
    if (dv == last_d && pv == last_p) return;
    last_d = dv; last_p = pv;
    const double k0d = dv / pv;
    if (k0d < GG2_KC && dv < GG2_DC) {
      // no cancellation to speak of: double
      const double k1d = (dv + 1.0) / pv;
      double PAv[12], Gv[12];
      (void) k1d; (void) PAv; (void) Gv;
      PAv[1] = R::psigamma(k0d, 1.0);
      PAv[2] = R::psigamma(k0d, 2.0);
      PAv[3] = R::psigamma(k0d, 3.0);
      Gv[0] = R::psigamma(k1d, 0.0) - R::psigamma(k0d, 0.0);
      Gv[1] = R::psigamma(k1d, 1.0) - R::psigamma(k0d, 1.0);
      Gv[2] = R::psigamma(k1d, 2.0) - R::psigamma(k0d, 2.0);
      coef_gengamma2_dexpected2_cpp<double>(dv, pv, PAv, Gv, 0.0, K.data());
    } else {
      const dd d(dv), p(pv);
      const dd k0 = d / p, k1 = (d + 1.0) / p;
      dd PAv[12], Gv[12];
      (void) k1; (void) PAv; (void) Gv;
      PAv[1] = dd_psi_n(k0, 1);
      PAv[2] = dd_psi_n(k0, 2);
      PAv[3] = dd_psi_n(k0, 3);
      Gv[0] = dd_psi_diff(k0, k1, 0);
      Gv[1] = dd_psi_diff(k0, k1, 1);
      Gv[2] = dd_psi_diff(k0, k1, 2);
      coef_gengamma2_dexpected2_cpp<dd>(d, p, PAv, Gv, dd(0.0), K.data());
    }
  };
  const bool scalar = n_m == 1 && n_d == 1 && n_p == 1;
  if (scalar) set_params(0);
  for (int i = 0; i < n; i++) {
    if (!scalar) set_params(i);
    const double im = 1.0 / mv;
    (void) im;
    o_mean_mean_mean_mean[i] = (K[0]) * std::pow(im, 4);
    o_mean_mean_d_d[i] = (K[1]) * std::pow(im, 2);
    o_mean_mean_p_p[i] = (K[2]) * std::pow(im, 2);
    o_mean_mean_mean_d[i] = (K[3]) * std::pow(im, 3);
    o_mean_mean_mean_p[i] = (K[4]) * std::pow(im, 3);
    o_mean_mean_d_p[i] = (K[5]) * std::pow(im, 2);
    o_d_d_mean_mean[i] = (K[6]) * std::pow(im, 2);
    o_d_d_d_d[i] = (K[7]);
    o_d_d_p_p[i] = (K[8]);
    o_d_d_mean_d[i] = (K[9]) * im;
    o_d_d_mean_p[i] = (K[10]) * im;
    o_d_d_d_p[i] = (K[11]);
    o_p_p_mean_mean[i] = (K[12]) * std::pow(im, 2);
    o_p_p_d_d[i] = (K[13]);
    o_p_p_p_p[i] = (K[14]);
    o_p_p_mean_d[i] = (K[15]) * im;
    o_p_p_mean_p[i] = (K[16]) * im;
    o_p_p_d_p[i] = (K[17]);
    o_mean_d_mean_mean[i] = (K[18]) * std::pow(im, 3);
    o_mean_d_d_d[i] = (K[19]) * im;
    o_mean_d_p_p[i] = (K[20]) * im;
    o_mean_d_mean_d[i] = (K[21]) * std::pow(im, 2);
    o_mean_d_mean_p[i] = (K[22]) * std::pow(im, 2);
    o_mean_d_d_p[i] = (K[23]) * im;
    o_mean_p_mean_mean[i] = (K[24]) * std::pow(im, 3);
    o_mean_p_d_d[i] = (K[25]) * im;
    o_mean_p_p_p[i] = (K[26]) * im;
    o_mean_p_mean_d[i] = (K[27]) * std::pow(im, 2);
    o_mean_p_mean_p[i] = (K[28]) * std::pow(im, 2);
    o_mean_p_d_p[i] = (K[29]) * im;
    o_d_p_mean_mean[i] = (K[30]) * std::pow(im, 2);
    o_d_p_d_d[i] = (K[31]);
    o_d_p_p_p[i] = (K[32]);
    o_d_p_mean_d[i] = (K[33]) * im;
    o_d_p_mean_p[i] = (K[34]) * im;
    o_d_p_d_p[i] = (K[35]);
  }
  (void) mv; (void) pv; (void) A0; (void) Z0;
  return List::create(Named("mean_mean_mean_mean") = o_mean_mean_mean_mean, Named("mean_mean_d_d") = o_mean_mean_d_d, Named("mean_mean_p_p") = o_mean_mean_p_p, Named("mean_mean_mean_d") = o_mean_mean_mean_d, Named("mean_mean_mean_p") = o_mean_mean_mean_p, Named("mean_mean_d_p") = o_mean_mean_d_p, Named("d_d_mean_mean") = o_d_d_mean_mean, Named("d_d_d_d") = o_d_d_d_d, Named("d_d_p_p") = o_d_d_p_p, Named("d_d_mean_d") = o_d_d_mean_d, Named("d_d_mean_p") = o_d_d_mean_p, Named("d_d_d_p") = o_d_d_d_p, Named("p_p_mean_mean") = o_p_p_mean_mean, Named("p_p_d_d") = o_p_p_d_d, Named("p_p_p_p") = o_p_p_p_p, Named("p_p_mean_d") = o_p_p_mean_d, Named("p_p_mean_p") = o_p_p_mean_p, Named("p_p_d_p") = o_p_p_d_p, Named("mean_d_mean_mean") = o_mean_d_mean_mean, Named("mean_d_d_d") = o_mean_d_d_d, Named("mean_d_p_p") = o_mean_d_p_p, Named("mean_d_mean_d") = o_mean_d_mean_d, Named("mean_d_mean_p") = o_mean_d_mean_p, Named("mean_d_d_p") = o_mean_d_d_p, Named("mean_p_mean_mean") = o_mean_p_mean_mean, Named("mean_p_d_d") = o_mean_p_d_d, Named("mean_p_p_p") = o_mean_p_p_p, Named("mean_p_mean_d") = o_mean_p_mean_d, Named("mean_p_mean_p") = o_mean_p_mean_p, Named("mean_p_d_p") = o_mean_p_d_p, Named("d_p_mean_mean") = o_d_p_mean_mean, Named("d_p_d_d") = o_d_p_d_d, Named("d_p_p_p") = o_d_p_p_p, Named("d_p_mean_d") = o_d_p_mean_d, Named("d_p_mean_p") = o_d_p_mean_p, Named("d_p_d_p") = o_d_p_d_p);
}

// the coefficients of gengamma2_cross_y_cpp, in double or in double-double
template <class T>
static void coef_gengamma2_cross_y_cpp(const T& d, const T& p, const T* PAv, const T* Gv, const T& Bs, double* K) {
  (void) d; (void) p; (void) PAv; (void) Gv; (void) Bs;
  const T G0 = Gv[0];
  const T c0 = d*p;
  const T c1 = G0*d;
  const T c2 = -c1;
  const T c3 = c1 - 1.0;
  const T c4 = -c3;
  const T c5 = d/p;
  const T c6 = -c5;
  const T c7 = G0 + c3;
  const T c8 = c5*c7;
  const T c9 = ((T(1.0) / T(5040.0)))*c5;
  const T c10 = Bs + G0 + c1;
  const T c11 = c5*(Bs + c7);
  K[0] = to_dbl(c0);
  K[1] = to_dbl(c0);
  K[2] = to_dbl(((T(1.0) / T(5040.0)))*c0);
  K[3] = to_dbl(((T(1.0) / T(720.0)))*c0);
  K[4] = to_dbl(((T(1.0) / T(120.0)))*c0);
  K[5] = to_dbl(((T(1.0) / T(24.0)))*c0);
  K[6] = to_dbl(((T(1.0) / T(6.0)))*c0);
  K[7] = to_dbl(((T(1.0) / T(2.0)))*c0);
  K[8] = to_dbl(c0);
  K[9] = to_dbl(c0);
  K[10] = to_dbl(c0);
  K[11] = to_dbl(c2);
  K[12] = to_dbl(c4);
  K[13] = to_dbl(-(T(1.0) / T(5040.0))*c1);
  K[14] = to_dbl(-(T(1.0) / T(720.0))*c1);
  K[15] = to_dbl(-(T(1.0) / T(120.0))*c1);
  K[16] = to_dbl(-(T(1.0) / T(24.0))*c1);
  K[17] = to_dbl(-(T(1.0) / T(6.0))*c1);
  K[18] = to_dbl(-(T(1.0) / T(2.0))*c1);
  K[19] = to_dbl(c2);
  K[20] = to_dbl(c2);
  K[21] = to_dbl(c4);
  K[22] = to_dbl(c6);
  K[23] = to_dbl(c6);
  K[24] = to_dbl(c8);
  K[25] = to_dbl(c8);
  K[26] = to_dbl(-c9);
  K[27] = to_dbl(c9*(c10 - 8.0));
  K[28] = to_dbl(((T(1.0) / T(720.0)))*c5*(c10 - 7.0));
  K[29] = to_dbl(((T(1.0) / T(120.0)))*c5*(c10 - 6.0));
  K[30] = to_dbl(((T(1.0) / T(24.0)))*c5*(c10 - 5.0));
  K[31] = to_dbl(((T(1.0) / T(6.0)))*c5*(c10 - 4.0));
  K[32] = to_dbl(((T(1.0) / T(2.0)))*c5*(c10 - 3.0));
  K[33] = to_dbl(c6);
  K[34] = to_dbl(c5*(c10 - 2.0));
  K[35] = to_dbl(c11);
  K[36] = to_dbl(c11);
}

// 1 in y and 1 in (mean, d, p)
// [[Rcpp::export]]
List gengamma2_cross_y_cpp(NumericVector y, NumericVector mean_, NumericVector d_, NumericVector p_) {
  const int n = y.size();
  const int n_m = mean_.size(), n_d = d_.size(), n_p = p_.size();
  NumericVector o_mean(n);
  NumericVector o_d(n);
  NumericVector o_p(n);
  std::vector<double> K(37);
  double mv = 0.0, pv = 0.0, A0 = 0.0, Z0 = 0.0;
  double last_d = R_NaN, last_p = R_NaN;
  auto set_params = [&](int i) {
    mv = mean_[i % n_m]; const double dv = d_[i % n_d]; pv = p_[i % n_p];
    // the coefficients depend on (d, p) alone
    if (dv == last_d && pv == last_p) return;
    last_d = dv; last_p = pv;
    const double k0d = dv / pv;
    if (k0d < GG2_KC && dv < GG2_DC) {
      // no cancellation to speak of: double
      const double k1d = (dv + 1.0) / pv;
      double PAv[12], Gv[12];
      (void) k1d; (void) PAv; (void) Gv;
      Gv[0] = R::psigamma(k1d, 0.0) - R::psigamma(k0d, 0.0);
      coef_gengamma2_cross_y_cpp<double>(dv, pv, PAv, Gv, gg2_B0(k0d), K.data());
    } else {
      const dd d(dv), p(pv);
      const dd k0 = d / p, k1 = (d + 1.0) / p;
      dd PAv[12], Gv[12];
      (void) k1; (void) PAv; (void) Gv;
      Gv[0] = dd_psi_diff(k0, k1, 0);
      coef_gengamma2_cross_y_cpp<dd>(d, p, PAv, Gv, dd_B0(k0), K.data());
    }
    A0 = gg2_A0(dv, pv); Z0 = A0 + gg2_B0(dv / pv);
  };
  const bool scalar = n_m == 1 && n_d == 1 && n_p == 1;
  if (scalar) set_params(0);
  for (int i = 0; i < n; i++) {
    if (!scalar) set_params(i);
    const double im = 1.0 / mv;
    (void) im;
    const double Yi = mv / y[i];
    (void) Yi;
    const double dy = y[i] - mv;
    const double pC = pv * (std::fabs(dy) < 0.5 * mv ? std::log1p(dy / mv) : std::log(y[i] / mv));
    const double Z = pC + Z0;
    if (std::fabs(Z) < 1.0) {
      const double R = gg2_R(Z);
      const double u0 = std::pow(Z, 7);
      const double u1 = std::pow(Z, 6);
      const double u2 = std::pow(Z, 5);
      const double u3 = std::pow(Z, 4);
      const double u4 = std::pow(Z, 3);
      const double u5 = std::pow(Z, 2);
      o_mean[i] = (Yi*(K[10] + K[2]*u0 + K[3]*u1 + K[4]*u2 + K[5]*u3 + K[6]*u4 + K[7]*u5 + K[8]*Z + K[9]*R)) * std::pow(im, 2);
      o_d[i] = (Yi*(K[13]*u0 + K[14]*u1 + K[15]*u2 + K[16]*u3 + K[17]*u4 + K[18]*u5 + K[19]*Z + K[20]*R + K[21])) * im;
      o_p[i] = (Yi*(K[26]*std::pow(Z, 8) + K[27]*u0 + K[28]*u1 + K[29]*u2 + K[30]*u3 + K[31]*u4 + K[32]*u5 + K[33]*R*Z + K[34]*Z + K[35]*R + K[36])) * im;
    } else {
      const double X = pC + A0;
      const double Q = std::expm1(Z);
      o_mean[i] = (Yi*(K[0]*Q + K[1])) * std::pow(im, 2);
      o_d[i] = (Yi*(K[11]*Q + K[12])) * im;
      o_p[i] = (Yi*(K[22]*Q*X + K[23]*X + K[24]*Q + K[25])) * im;
    }
  }
  (void) mv; (void) pv; (void) A0; (void) Z0;
  return List::create(Named("mean") = o_mean, Named("d") = o_d, Named("p") = o_p);
}

// the coefficients of gengamma2_cross2_y_cpp, in double or in double-double
template <class T>
static void coef_gengamma2_cross2_y_cpp(const T& d, const T& p, const T* PAv, const T* Gv, const T& Bs, double* K) {
  (void) d; (void) p; (void) PAv; (void) Gv; (void) Bs;
  const T G0 = Gv[0];
  const T c0 = p - 1.0;
  const T c1 = c0*d;
  const T c2 = c1*p;
  const T c3 = G0*d;
  const T c4 = -c0*c3;
  const T c5 = c3*p - c3;
  const T c6 = c5 + 1.0;
  const T c7 = -c6;
  const T c8 = pw(p, -1);
  const T c9 = c1*c8;
  const T c10 = -c9;
  const T c11 = G0*p - G0;
  const T c12 = c11 + c6 - 2.0*p;
  const T c13 = c8*d;
  const T c14 = c12*c13;
  const T c15 = Bs*p - Bs;
  const T c16 = c11 + c15 + c5;
  const T c17 = c13*(c12 + c15);
  K[0] = to_dbl(c2);
  K[1] = to_dbl(c2);
  K[2] = to_dbl(((T(1.0) / T(5040.0)))*c2);
  K[3] = to_dbl(((T(1.0) / T(720.0)))*c2);
  K[4] = to_dbl(((T(1.0) / T(120.0)))*c2);
  K[5] = to_dbl(((T(1.0) / T(24.0)))*c2);
  K[6] = to_dbl(((T(1.0) / T(6.0)))*c2);
  K[7] = to_dbl(((T(1.0) / T(2.0)))*c2);
  K[8] = to_dbl(c2);
  K[9] = to_dbl(c2);
  K[10] = to_dbl(c2);
  K[11] = to_dbl(c4);
  K[12] = to_dbl(c7);
  K[13] = to_dbl(((T(1.0) / T(5040.0)))*c4);
  K[14] = to_dbl(((T(1.0) / T(720.0)))*c4);
  K[15] = to_dbl(((T(1.0) / T(120.0)))*c4);
  K[16] = to_dbl(((T(1.0) / T(24.0)))*c4);
  K[17] = to_dbl(((T(1.0) / T(6.0)))*c4);
  K[18] = to_dbl(((T(1.0) / T(2.0)))*c4);
  K[19] = to_dbl(c4);
  K[20] = to_dbl(c4);
  K[21] = to_dbl(c7);
  K[22] = to_dbl(c10);
  K[23] = to_dbl(c10);
  K[24] = to_dbl(c14);
  K[25] = to_dbl(c14);
  K[26] = to_dbl(-(T(1.0) / T(5040.0))*c9);
  K[27] = to_dbl(((T(1.0) / T(5040.0)))*c13*(c16 - 9.0*p + 8.0));
  K[28] = to_dbl(((T(1.0) / T(720.0)))*c13*(c16 - 8.0*p + 7.0));
  K[29] = to_dbl(((T(1.0) / T(120.0)))*c13*(c16 - 7.0*p + 6.0));
  K[30] = to_dbl(((T(1.0) / T(24.0)))*c13*(c16 - 6.0*p + 5.0));
  K[31] = to_dbl(((T(1.0) / T(6.0)))*c13*(c16 - 5.0*p + 4.0));
  K[32] = to_dbl(((T(1.0) / T(2.0)))*c13*(c16 - 4.0*p + 3.0));
  K[33] = to_dbl(c10);
  K[34] = to_dbl(c13*(c16 - 3.0*p + 2.0));
  K[35] = to_dbl(c17);
  K[36] = to_dbl(c17);
}

