// 2 in y and 2 in (mean, d, p)
// [[Rcpp::export]]
List gengamma2_hess_y_hess_cpp(NumericVector y, NumericVector mean_, NumericVector d_, NumericVector p_) {
  const int n = y.size();
  const int n_m = mean_.size(), n_d = d_.size(), n_p = p_.size();
  NumericVector o_mean_mean(n);
  NumericVector o_d_d(n);
  NumericVector o_p_p(n);
  NumericVector o_mean_d(n);
  NumericVector o_mean_p(n);
  NumericVector o_d_p(n);
  std::vector<double> K(82);
  double mv = 0.0, pv = 0.0, A0 = 0.0, Z0 = 0.0;
  double last_d = R_NaN, last_p = R_NaN;
  auto set_params = [&](int i) {
    mv = mean_[i % n_m]; const double dv = d_[i % n_d]; pv = p_[i % n_p];
    // the coefficients depend on (d, p) alone
    if (dv == last_d && pv == last_p) return;
    last_d = dv; last_p = pv;
    const double k0d = dv / pv;
    if (k0d < GG2_KC && dv < GG2_DC) {
      // no cancellation to speak of: double
      const double k1d = (dv + 1.0) / pv;
      double PAv[12], Gv[12];
      (void) k1d; (void) PAv; (void) Gv;
      PAv[1] = R::psigamma(k0d, 1.0);
      Gv[0] = R::psigamma(k1d, 0.0) - R::psigamma(k0d, 0.0);
      Gv[1] = R::psigamma(k1d, 1.0) - R::psigamma(k0d, 1.0);
      coef_gengamma2_hess_y_hess_cpp<double>(dv, pv, PAv, Gv, gg2_B0(k0d), K.data());
    } else {
      const dd d(dv), p(pv);
      const dd k0 = d / p, k1 = (d + 1.0) / p;
      dd PAv[12], Gv[12];
      (void) k1; (void) PAv; (void) Gv;
      PAv[1] = dd_psi_n(k0, 1);
      Gv[0] = dd_psi_diff(k0, k1, 0);
      Gv[1] = dd_psi_diff(k0, k1, 1);
      coef_gengamma2_hess_y_hess_cpp<dd>(d, p, PAv, Gv, dd_B0(k0), K.data());
    }
    A0 = gg2_A0(dv, pv); Z0 = A0 + gg2_B0(dv / pv);
  };
  const bool scalar = n_m == 1 && n_d == 1 && n_p == 1;
  if (scalar) set_params(0);
  for (int i = 0; i < n; i++) {
    if (!scalar) set_params(i);
    const double im = 1.0 / mv;
    (void) im;
    const double Yi = mv / y[i];
    (void) Yi;
    const double dy = y[i] - mv;
    const double pC = pv * (std::fabs(dy) < 0.5 * mv ? std::log1p(dy / mv) : std::log(y[i] / mv));
    const double Z = pC + Z0;
    if (std::fabs(Z) < 1.0) {
      const double R = gg2_R(Z);
      const double u0 = std::pow(Yi, 2);
      const double u1 = std::pow(Z, 7);
      const double u2 = std::pow(Z, 6);
      const double u3 = std::pow(Z, 5);
      const double u4 = std::pow(Z, 4);
      const double u5 = std::pow(Z, 3);
      const double u6 = std::pow(Z, 2);
      const double u7 = R*Z;
      const double u8 = std::pow(Z, 8);
      o_mean_mean[i] = (u0*(K[10] + K[2]*u1 + K[3]*u2 + K[4]*u3 + K[5]*u4 + K[6]*u5 + K[7]*u6 + K[8]*Z + K[9]*R)) * std::pow(im, 4);
      o_d_d[i] = (u0*(K[13]*u1 + K[14]*u2 + K[15]*u3 + K[16]*u4 + K[17]*u5 + K[18]*u6 + K[19]*Z + K[20]*R + K[21])) * std::pow(im, 2);
      o_p_p[i] = (u0*(K[28]*std::pow(Z, 9) + K[29]*u8 + K[30]*u1 + K[31]*u2 + K[32]*u3 + K[33]*u4 + K[34]*u5 + K[35]*R*u6 + K[36]*u6 + K[37]*u7 + K[38]*Z + K[39]*R + K[40])) * std::pow(im, 2);
      o_mean_d[i] = (u0*(K[43]*u1 + K[44]*u2 + K[45]*u3 + K[46]*u4 + K[47]*u5 + K[48]*u6 + K[49]*Z + K[50]*R + K[51])) * std::pow(im, 3);
      o_mean_p[i] = (u0*(K[56]*u8 + K[57]*u1 + K[58]*u2 + K[59]*u3 + K[60]*u4 + K[61]*u5 + K[62]*u6 + K[63]*u7 + K[64]*Z + K[65]*R + K[66])) * std::pow(im, 3);
      o_d_p[i] = (u0*(K[71]*u8 + K[72]*u1 + K[73]*u2 + K[74]*u3 + K[75]*u4 + K[76]*u5 + K[77]*u6 + K[78]*u7 + K[79]*Z + K[80]*R + K[81])) * std::pow(im, 2);
    } else {
      const double X = pC + A0;
      const double Q = std::expm1(Z);
      const double u0 = std::pow(Yi, 2);
      const double u1 = Q*X;
      const double u2 = std::pow(X, 2);
      o_mean_mean[i] = (u0*(K[0]*Q + K[1])) * std::pow(im, 4);
      o_d_d[i] = (u0*(K[11]*Q + K[12])) * std::pow(im, 2);
      o_p_p[i] = (u0*(K[22]*Q*u2 + K[23]*u2 + K[24]*u1 + K[25]*X + K[26]*Q + K[27])) * std::pow(im, 2);
      o_mean_d[i] = (u0*(K[41]*Q + K[42])) * std::pow(im, 3);
      o_mean_p[i] = (u0*(K[52]*u1 + K[53]*X + K[54]*Q + K[55])) * std::pow(im, 3);
      o_d_p[i] = (u0*(K[67]*u1 + K[68]*X + K[69]*Q + K[70])) * std::pow(im, 2);
    }
  }
  (void) mv; (void) pv; (void) A0; (void) Z0;
  return List::create(Named("mean_mean") = o_mean_mean, Named("d_d") = o_d_d, Named("p_p") = o_p_p, Named("mean_d") = o_mean_d, Named("mean_p") = o_mean_p, Named("d_p") = o_d_p);
}

// the coefficients of gengamma2_dy1_cpp, in double or in double-double
template <class T>
static void coef_gengamma2_dy1_cpp(const T& d, const T& p, const T* PAv, const T* Gv, const T& Bs, double* K) {
  (void) d; (void) p; (void) PAv; (void) Gv; (void) Bs;
  const T c0 = -d;
  K[0] = to_dbl(c0);
  K[1] = to_dbl(-1.0);
  K[2] = to_dbl(-(T(1.0) / T(5040.0))*d);
  K[3] = to_dbl(-(T(1.0) / T(720.0))*d);
  K[4] = to_dbl(-(T(1.0) / T(120.0))*d);
  K[5] = to_dbl(-(T(1.0) / T(24.0))*d);
  K[6] = to_dbl(-(T(1.0) / T(6.0))*d);
  K[7] = to_dbl(-(T(1.0) / T(2.0))*d);
  K[8] = to_dbl(c0);
  K[9] = to_dbl(c0);
  K[10] = to_dbl(-1.0);
}

