  K[0] = to_dbl(c0);
  K[1] = to_dbl(c1);
  K[2] = to_dbl(((T(1.0) / T(5040.0)))*c0);
  K[3] = to_dbl(((T(1.0) / T(720.0)))*c0);
  K[4] = to_dbl(((T(1.0) / T(120.0)))*c0);
