  K[6] = to_dbl(((T(1.0) / T(6.0)))*c0);
  K[7] = to_dbl(((T(1.0) / T(2.0)))*c0);
  K[8] = to_dbl(c0);
  K[9] = to_dbl(c0);
  K[10] = to_dbl(c1);
